def retry_decision(method, status, attempt, retry_after=None):
    if method != 'GET' or status not in (429, 503) or attempt >= 3:
        return ('stop', 0)
    if retry_after is not None:
        if not retry_after.isdecimal():
            return ('stop: unsupported Retry-After', 0)
        delay = int(retry_after)
        if delay > 5:
            return ('stop: delay too long', 0)
        return ('retry', delay)
    return ('retry', min(2 ** (attempt - 1), 5))

assert retry_decision('GET', 429, 1, '2') == ('retry', 2)
assert retry_decision('POST', 503, 1) == ('stop', 0)
assert retry_decision('GET', 503, 3) == ('stop', 0)
assert retry_decision('GET', 503, 1, 'tomorrow')[0].startswith('stop')
print('policy checks passed')
